/* Research brief patterns */
.hac-kicker{text-transform:uppercase;letter-spacing:.08em;font-size:.8rem!important;font-weight:700;color:#164a5b}
.hac-meta{color:#5b6561;font-size:.95rem}
.hac-findings{background:#f4f6f3;border-left:4px solid #1f5f74;padding:1.25rem 1.5rem!important}
.hac-findings h2{font-size:1rem!important;text-transform:uppercase;letter-spacing:.06em;color:#164a5b;margin-top:0!important}
.hac-stats{gap:1px!important;background:#d9dedb;border:1px solid #d9dedb}
.hac-stats > .wp-block-group{background:#fff;padding:1rem 1.1rem!important}
.hac-stat-num{font-size:2rem!important;font-weight:700;line-height:1.1!important;margin:0!important}
.hac-stat-label{font-size:.92rem!important;color:#5b6561;margin:.3rem 0 0!important}
.hac-notes{font-size:.92rem}
.hac-concept{background:#1d2321;color:#f1f3f1;font:400 14px/1.45 system-ui,sans-serif;padding:.55rem 1.25rem;text-align:center}
.hac-concept a{color:#f1f3f1}
.screen-reader-text{border:0;clip:rect(1px,1px,1px,1px);clip-path:inset(50%);height:1px;margin:-1px;overflow:hidden;padding:0;position:absolute;width:1px;word-wrap:normal!important}

( function ( wp ) {
	var el = wp.element.createElement;
	var useEffect = wp.element.useEffect;
	var __ = wp.i18n.__;
	var be = wp.blockEditor;
	var c = wp.components;
	var ServerSideRender = wp.serverSideRender;
	var LOCK = 'hac-chart-description';

	function countRows( data ) {
		var lines = ( data || '' ).trim().split( /\r?\n/ ).filter( Boolean );
		return Math.max( lines.length - 1, 0 );
	}

	wp.blocks.registerBlockType( 'hac/chart', {
		edit: function ( props ) {
			var a = props.attributes;
			var set = props.setAttributes;
			var blockProps = be.useBlockProps( { className: 'hac-chart-editor' } );
			var missing = ! ( a.description || '' ).trim();

			// Ask for a description before the post can be published.
			useEffect( function () {
				var ed = wp.data.dispatch( 'core/editor' );
				if ( ! ed || ! ed.lockPostSaving ) { return; }
				var key = LOCK + '-' + props.clientId;
				if ( missing ) { ed.lockPostSaving( key ); } else { ed.unlockPostSaving( key ); }
				return function () { ed.unlockPostSaving( key ); };
			}, [ missing, props.clientId ] );

			return el( 'div', blockProps,
				el( be.InspectorControls, {},
					el( c.PanelBody, { title: __( 'Chart settings' ), initialOpen: true },
						el( c.SelectControl, {
							label: __( 'Chart type' ),
							value: a.chartType,
							options: [
								{ label: __( 'Columns' ), value: 'bar' },
								{ label: __( 'Bars (horizontal)' ), value: 'hbar' },
								{ label: __( 'Stacked to 100%' ), value: 'stacked' }
							],
							onChange: function ( v ) { set( { chartType: v } ); }
						} ),
						el( c.TextControl, {
							label: __( 'Unit after values (optional)' ),
							help: __( 'For example % or " homes"' ),
							value: a.unit,
							onChange: function ( v ) { set( { unit: v } ); }
						} ),
						el( c.ToggleControl, {
							label: __( 'Sort largest first' ),
							checked: !! a.sort,
							onChange: function ( v ) { set( { sort: v } ); }
						} )
					)
				),
				el( 'div', { className: 'hac-chart-editor__fields' },
					el( c.TextControl, {
						label: __( 'Chart title' ),
						value: a.title,
						onChange: function ( v ) { set( { title: v } ); }
					} ),
					el( c.TextareaControl, {
						label: __( 'Data: paste from a spreadsheet' ),
						help: __( 'First row is the column names; first column is the labels. Each extra column becomes a series readers can switch between. ' ) + countRows( a.data ) + __( ' rows.' ),
						rows: 6,
						className: 'hac-chart-editor__data',
						value: a.data,
						onChange: function ( v ) { set( { data: v } ); }
					} ),
					el( c.TextareaControl, {
						label: __( 'Description for screen readers and search (required)' ),
						help: __( 'One or two sentences that say what the chart shows.' ),
						rows: 2,
						value: a.description,
						onChange: function ( v ) { set( { description: v } ); }
					} ),
					missing ? el( c.Notice, { status: 'warning', isDismissible: false }, __( 'Add a description to publish. It becomes the chart’s text alternative.' ) ) : null,
					el( c.TextControl, {
						label: __( 'Source line' ),
						value: a.source,
						onChange: function ( v ) { set( { source: v } ); }
					} )
				),
				el( 'div', { className: 'hac-chart-editor__preview' },
					el( 'p', { className: 'hac-chart-editor__label' }, __( 'Preview' ) ),
					el( ServerSideRender, { block: 'hac/chart', attributes: a } )
				)
			);
		},
		save: function () { return null; }
	} );
} )( window.wp );

.hac-chart{margin:2rem 0;padding:1.25rem;border:1px solid #d9dedb;border-radius:6px;background:#fff;color:#1d2321}
.hac-chart__head{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;flex-wrap:wrap;margin-bottom:.5rem}
.hac-chart__title{margin:0!important;font-size:1.1rem!important;line-height:1.3;font-weight:700!important}
.hac-chart__series{display:inline-flex;border:1px solid #d9dedb;border-radius:4px;overflow:hidden}
.hac-chart__series button{font:inherit;font-size:.85rem;border:0;background:#fff;padding:.3rem .7rem;cursor:pointer;color:#3b4441}
.hac-chart__series button[aria-pressed="true"]{background:#1f5f74;color:#fff}
.hac-chart__plot{overflow-x:auto}
.hac-chart__plot svg{display:block;width:100%;height:auto}
.hac-chart--bar .hac-chart__plot svg{min-width:34rem}
.hac-chart__bar{fill:#e9b54a}
.hac-chart--stacked .hac-chart__bar{fill:#1f5f74}
.hac-chart__bar:hover,.hac-chart__bar:focus{fill:#a6442a;outline:none}
.hac-chart__rest{fill:#e4e8e5}
.hac-chart__grid{stroke:#e6e9e7}
.hac-chart__axis{stroke:#8a948f}
.hac-chart__tick{font-size:11px;fill:#3b4441}
.hac-chart__lab,.hac-chart__val{font-size:14px;fill:#1d2321}
.hac-chart__val{font-weight:700}
.hac-chart__source{font-size:.88rem;color:#5b6561;margin-top:.6rem}
.hac-chart__data{margin-top:.6rem}
.hac-chart__data summary{cursor:pointer;font-weight:600;color:#164a5b;font-size:.92rem}
.hac-chart__tablewrap{overflow:auto;max-height:24rem;margin-top:.5rem;border:1px solid #d9dedb}
.hac-chart table{border-collapse:collapse;width:100%;font-size:.9rem;margin:0}
.hac-chart caption{text-align:left;font-weight:600;padding:.5rem .6rem}
.hac-chart th,.hac-chart td{padding:.35rem .6rem;border-bottom:1px solid #d9dedb;text-align:right;white-space:nowrap}
.hac-chart th:first-child,.hac-chart td:first-child{text-align:left}
.hac-chart thead th{position:sticky;top:0;background:#f4f6f3}
.hac-chart-editor{border:1px dashed #b9c2bd;padding:1rem;border-radius:6px;background:#fbfcfb}
.hac-chart-editor__data textarea{font-family:ui-monospace,Menlo,monospace;font-size:12px}
.hac-chart-editor__label{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#5b6561;margin:1rem 0 .25rem}

document.addEventListener( 'click', function ( e ) {
	var btn = e.target.closest( '.hac-chart__series button' );
	if ( ! btn ) { return; }
	var fig = btn.closest( '.hac-chart' );
	var i = btn.getAttribute( 'data-series' );
	fig.querySelectorAll( '.hac-chart__series button' ).forEach( function ( b ) {
		b.setAttribute( 'aria-pressed', b === btn ? 'true' : 'false' );
	} );
	fig.querySelectorAll( '.hac-chart__plot' ).forEach( function ( p ) {
		p.hidden = p.getAttribute( 'data-series' ) !== i;
	} );
} );
